(5073, 1, 16, 3769, 1073741888, 0, 11, 0, 230, 0, 53, 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 'Flaxwhisker Front', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0),
(5074, 1, 16, 3770, 1073741888, 0, 11, 0, 9, 0, 51, 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 'Bloodfist Point', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(91775, 0, 0, 'Foreign interference detected! Dispatch threat!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66820'),
(91770, 0, 0, 'Now, I just put this here, and then...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66821'),
(91770, 1, 0, 'That\'s done it, I knew the Turbo-Charged Wobblefree Fizz-disk would come in handy.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66822'),
(91722, 0, 0, 'Hmm, now that you mention it, I do recall such a figure. He was a muscular orc, quite friendly, too. During the demonic invasion a few years back, he spoke with me seeking to do battle within the Temple of Arkkoran. That was the last I saw of him. Hopefully this helps your search.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66677'),
(91722, 1, 0, 'We Keepers have been active within Azshara to leave the secrets of the region a mystery. We have fallen into shadow, into dissaray unable to even communicate effectively with one another, and spread over large distances. We are surrounded by enemies at all sides and what once was is nothing more then a faded memory of ruins.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 90261'),
(91722, 2, 0, 'It has been a long time since I have had the chance to wield my magic in such a manner, and now, crafting this Staff of Eldara has granted me some glimmer of hope.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 90262'),
(91722, 3, 0, 'It is done...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 4450'),
(92196, 0, 0, 'You have honored the dead, may his soul be guided safely to his fellow masters.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66688'),
(92197, 0, 0, 'Spirits of Azshara, heed my call. Tell me, what is happening to this land.', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66428'),
(92197, 1, 0, 'I see... A radiant city... full of people.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66416'),
(92197, 2, 0, 'They are dying... A great wave swallows them all.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66417'),
(92197, 3, 0, 'Magical energies, waning, blue crystals... A roar.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66418'),
(92197, 4, 0, 'A shadow... Of a dragon?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66419'),
(92197, 5, 0, 'This is all... I need a rest.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66420'),
(91350, 0, 0, 'Now, let us see if the dampening has been halted...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67017'),
(91350, 1, 0, 'It would appear our efforts have been meaningless... We must think of a new solution...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67018'),
(91350, 2, 0, 'Thanks again $N, travel safely, you are a hero to the Kirin Tor.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67034'),
(61979, 0, 0, 'That charlatan is a farce, like every mortal sorcerer! The magic of Azeroth belongs to the only ones who are truly able to wield and comprehend it!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 30180');
